<?php require __DIR__.'/includes/bootstrap.php';
if(empty($_SESSION['cart'])) shop_redirect('cart.php');
$items=cart_items();if(!$items)shop_redirect('cart.php');
$subtotal=cart_subtotal();$errors=[];$values=['full_name'=>'','email'=>'','phone'=>'','delivery_method'=>'pickup','county'=>'','address'=>'','notes'=>''];$max_attempts=5;$attempt_key='shop_checkout_attempts';if(!isset($_SESSION[$attempt_key]))$_SESSION[$attempt_key]=[];$_SESSION[$attempt_key]=array_filter($_SESSION[$attempt_key],fn($t)=>time()-$t<900);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf()){http_response_code(403);$errors['_form']='Your session expired. Please refresh and try again.';}
    elseif(count($_SESSION[$attempt_key])>= $max_attempts){http_response_code(429);$errors['_form']='Too many checkout attempts. Please wait before trying again.';}
    else{
        $_SESSION[$attempt_key][]=time();[$values,$errors]=shop_validate_checkout($_POST,$config);
        if(!isset($_POST['order_nonce'])||!isset($_SESSION['checkout_nonce'])||!hash_equals($_SESSION['checkout_nonce'],(string)$_POST['order_nonce']))$errors['_form']='This checkout form has already been submitted. Please review your cart.';
        if(!$errors){
            // Revalidate quantity and stock from server-side catalogue; browser prices are never used.
            $validated=[];$valid_subtotal=0;foreach($items as $item){$current=shop_product($item['product']['id']);if(!$current||$item['quantity']>(int)$current['stock']){$errors['_form']='Stock changed while you were checking out. Please update your cart.';break;}$line=(int)$current['price']*(int)$item['quantity'];$validated[]=['product'=>['id'=>$current['id'],'name'=>$current['name'],'sku'=>$current['sku'],'price'=>(int)$current['price'],'main_image'=>$current['main_image']],'quantity'=>(int)$item['quantity'],'line_total'=>$line];$valid_subtotal+=$line;}
            if(!$errors){$delivery=$config['delivery'][$values['delivery_method']];$delivery_fee=(int)$delivery['fee'];$customer=['full_name'=>$values['full_name'],'email'=>$values['email'],'phone'=>$values['phone'],'county'=>$values['county'],'address'=>$values['address'],'notes'=>$values['notes']];$created=shop_create_order($customer,$validated,$valid_subtotal,$delivery_fee,$values['delivery_method']);if(!$created['ok']){$errors['_form']='The order could not be created. Please try again.';}else{$_SESSION['confirmed_orders'][$created['order']['order_number']]=true;unset($_SESSION['checkout_nonce']);$_SESSION['cart']=[];$_SESSION[$attempt_key]=[];shop_redirect('confirmation.php?order='.urlencode($created['order']['order_number']));}}
        }
    }
}
if(empty($_SESSION['checkout_nonce']))$_SESSION['checkout_nonce']=bin2hex(random_bytes(16));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | TraveL Den Shop</title><meta name="description" content="Checkout for physical artefacts and trinkets in Kenyan Shillings."><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/shop/assets/css/shop.css"></head><body><?php require __DIR__.'/includes/header.php'; ?>
<h1>Checkout</h1><p class="sample-banner">Sample checkout. No real payment is collected and payment remains pending.</p><div class="checkout-layout"><form id="checkout-form" class="checkout-form" method="post" novalidate><?= csrf_field() ?><input type="hidden" name="order_nonce" value="<?= shop_e($_SESSION['checkout_nonce']) ?>"><?php if(!empty($errors['_form'])):?><p class="notice error"><?= shop_e($errors['_form']) ?></p><?php endif;
$fields=[['full_name','Full name','text'],['email','Email address','email'],['phone','Phone number','tel'],['county','County or location','text']];foreach($fields as [$name,$label,$type]):?><div class="field"><label for="<?= $name ?>"><?= $label ?> <span aria-hidden="true">*</span></label><input id="<?= $name ?>" name="<?= $name ?>" type="<?= $type ?>" value="<?= shop_e($values[$name]) ?>" required autocomplete="<?= $name==='email'?'email':($name==='phone'?'tel':'name') ?>" aria-invalid="<?= isset($errors[$name])?'true':'false' ?>" aria-describedby="<?= $name ?>-error"><?php if(isset($errors[$name])):?><span id="<?= $name ?>-error" class="error"><?= shop_e($errors[$name]) ?></span><?php endif;?></div><?php endforeach;?><div class="field"><label for="delivery_method">Delivery method *</label><select id="delivery_method" name="delivery_method" required><?php foreach($config['delivery'] as $key=>$delivery):?><option value="<?= shop_e($key) ?>" <?= $values['delivery_method']===$key?'selected':'' ?>><?= shop_e($delivery['label']) ?><?= $delivery['fee']>0?' — '.shop_money($delivery['fee']).' KES':'' ?></option><?php endforeach;?></select><?php if(isset($errors['delivery_method'])):?><span class="error"><?= shop_e($errors['delivery_method']) ?></span><?php endif;?></div><div class="field"><label for="address">Delivery address</label><textarea id="address" name="address" autocomplete="street-address" aria-describedby="address-error"><?= shop_e($values['address']) ?></textarea><small>Required for local delivery and courier shipping.</small><?php if(isset($errors['address'])):?><span id="address-error" class="error"><?= shop_e($errors['address']) ?></span><?php endif;?></div><div class="field"><label for="notes">Order notes (optional)</label><textarea id="notes" name="notes" maxlength="1000"><?= shop_e($values['notes']) ?></textarea></div><button class="shop-button" type="submit">Place sample order</button></form><aside class="cart-summary"><h2>Order summary</h2><div class="summary-row"><span>Subtotal</span><strong><?= shop_money($subtotal) ?> KES</strong></div><div id="delivery-summary" class="summary-row"><span>Selected delivery</span><strong id="delivery-fee"><?= shop_money($config['delivery'][$values['delivery_method']]['fee']) ?> KES</strong></div><div class="summary-row"><strong>Total</strong><strong id="order-total"><?= shop_money($subtotal+(int)$config['delivery'][$values['delivery_method']]['fee']) ?> KES</strong></div><p><small id="delivery-note"><?= shop_e($config['delivery'][$values['delivery_method']]['description']) ?></small></p></aside></div><script>const deliveryData=<?= json_encode(array_map(fn($d)=>['fee'=>(int)$d['fee'],'description'=>$d['description']],$config['delivery']),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;const subtotal=<?= (int)$subtotal ?>;const select=document.getElementById('delivery_method');function updateDelivery(){const data=deliveryData[select.value];const fee=data?.fee||0;document.getElementById('delivery-fee').textContent=new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES'}).format(fee);document.getElementById('order-total').textContent=new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES'}).format(subtotal+fee);document.getElementById('delivery-note').textContent=data?.description||'';}select?.addEventListener('change',updateDelivery);</script><?php require __DIR__.'/includes/footer.php'; ?></body></html>
